---RefreshByQuestId 根据关卡id刷新版式
---@param questId integer @ 关卡id
---@param passedQuestId integer @ 通过的关卡id
function GachaCoinQuestModeChange:RefreshByQuestId(questId, passedQuestId)
    -- 根据关卡类型刷新版式
    local questType = GCQUtils.GetGachaCoinQuestTypeById(questId)
    self:RefreshByQuestType(questType)

    -- 根据是否解锁刷新版式
    local unlockChallenge = GCQUtils.IsCQuestUnlock(questId, passedQuestId)
    self:RefreshByUnlock(unlockChallenge)
end

---RefreshByQuestType 根据关卡类型刷新版式
---@param questType GachaCoinQuestConstants.Defines.QuestType
function GachaCoinQuestModeChange:RefreshByQuestType(questType)
    -- 设置当前模式
    self:SetCurrentQuestType(questType)
end

---RefreshByUnlock 根据根据是否解锁刷新版式
---@param unlock boolean @ 是否解锁挑战模式关卡
function GachaCoinQuestModeChange:RefreshByUnlock(unlock)
    -- 锁定模块
    KTool.SetActive(self.LockIconChallenge.gameObject, not unlock)
    self.LabelChallenge.color = XLuaUtils.HexToColor((not unlock) and LockedTxtColor or UnlockedTxtColor)
    -- 选中模块
    if unlock then
        local targetQuestType = GCQConstants.Defines.QuestType.Challenge + GCQConstants.Defines.QuestType.Normal - self:GetCurrentQuestType()
        local isNormal = targetQuestType == GCQConstants.Defines.QuestType.Normal
        local isChallenge = targetQuestType == GCQConstants.Defines.QuestType.Challenge
        KTool.SetActive(self.Group1.gameObject, isChallenge)
        KTool.SetActive(self.Group2.gameObject, isNormal)
    end
end

-----RefreshCountdown 刷新倒计时
---@param countdown integer @ 倒计时 秒
function GachaCoinQuestModeChange:RefreshCountdown(countdown)
    local cdDescr = GCQUtils.GetCountdownDescrByCd(countdown)
    self.TimerLabel.text = cdDescr
end
